package com.google.javascript.jscomp;

import com.google.common.base.Function;
import com.google.common.collect.ImmutableMap;
import com.google.javascript.jscomp.phases.AbstractPass;
import com.google.javascript.jscomp.types.JSType;
import com.google.javascript.jscomp.types.TypeError;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.jstype.FunctionType;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.JSTypeRegistry;
import com.google.javascript.rhino.jstype.ObjectType;
import com.google.javascript.rhino.jstype.Visitor;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.AssertLoose.assertEquals;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ClosureReverseAbstractInterpreter_getPreciserScopeKnowingConditionOutcome_TriageGen2Test {

    private ClosureReverseAbstractInterpreter interpreter;

    @Mock private Node condition;
    @Mock private Node callee;
    @Mock private Node param;
    @Mock private Node left;
    @Mock private Node right;
    @Mock private FlowScope blindScope;
    @Mock private FlowScope expectedScope;
    @Mock private JSType paramType;
    @Mock private Function<TypeRestriction, JSType> restricter;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // We spy on the interpreter to mock the internal calls like getTypeIfRefinable 
        // and nextPreciserScopeKnowingConditionOutcome which are part of the same class.
        interpreter = spy(new ClosureReverseAbstractInterpreter());
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_Fallback() {
        // Test case where condition type is not CALL
        when(condition.getType()).thenReturn(Node.Type.EXPRESSION);
        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true)).thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
        verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_WrongChildCount() {
        // Test case where condition is CALL but child count is not 2
        when(condition.getType()).thenReturn(Node.Type.CALL);
        when(condition.getChildCount()).thenReturn(1);
        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true)).thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_CalleeNotGetProp() {
        when(condition.getType()).thenReturn(Node.Type.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(Node.Type.NAME); // Not GETPROP

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true)).thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_ParamNotQualifiedName() {
        when(condition.getType()).thenReturn(Node.Type.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(Node.Type.GETPROP);
        when(param.isQualifiedName()).thenReturn(false);

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true)).thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_ParamTypeNotRefinable() {
        when(condition.getType()).thenReturn(Node.Type.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(Node.Type.GETPROP);
        when(param.isQualifiedName()).thenReturn(true);

        // Mock getTypeIfRefinable to return null
        when(interpreter.getTypeIfRefinable(param, blindScope)).thenReturn(null);
        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true)).thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_LeftNotGoog() {
        when(condition.getType()).thenReturn(Node.Type.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(Node.Type.GETPROP);
        when(param.isQualifiedName()).thenReturn(true);
        when(interpreter.getTypeIfRefinable(param, blindScope)).thenReturn(paramType);

        when(callee.getFirstChild()).thenReturn(left);
        when(callee.getLastChild()).thenReturn(right);
        when(left.getType()).thenReturn(Node.Type.NAME);
        when(left.getString()).thenReturn("notgoog"); // Not "goog"

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true)).thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_RightNotString() {
        when(condition.getType()).thenReturn(Node.Type.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(Node.Type.GETPROP);
        when(param.isQualifiedName()).thenReturn(true);
        when(interpreter.getTypeIfRefinable(param, blindScope)).thenReturn(paramType);

        when(callee.getFirstChild()).thenReturn(left);
        when(callee.getLastChild()).thenReturn(right);
        when(left.getType()).thenReturn(Node.Type.NAME);
        when(left.getString()).thenReturn("goog");
        when(right.getType()).thenReturn(Node.Type.NUMBER); // Not STRING

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true)).thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_RestricterNotFound() {
        when(condition.getType()).thenReturn(Node.Type.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(Node.Type.GETPROP);
        when(param.isQualifiedName()).thenReturn(true);
        when(interpreter.getTypeIfRefinable(param, blindScope)).thenReturn(paramType);

        when(callee.getFirstChild()).thenReturn(left);
        when(callee.getLastChild()).thenReturn(right);
        when(left.getType()).thenReturn(Node.Type.NAME);
        when(left.getString()).thenReturn("goog");
        when(right.getType()).thenReturn(Node.Type.STRING);
        when(right.getString()).thenReturn("UNKNOWN_KEY");

        // Mocking the 'restricters' map access is tricky since it's a private field. 
        // In a real scenario, we'd use reflection or ensure the interpreter is initialized with a map.
        // Here we assume 'restricters' is empty or doesn't contain "UNKNOWN_KEY".

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true)).thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
    }

    @Test
    public void testGetPreciserScopeKnowingConditionOutcome_Success() throws Exception {
        // Setup the complex success path
        when(condition.getType()).thenReturn(Node.Type.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(Node.Type.GETPROP);
        when(param.isQualifiedName()).thenReturn(true);
        when(interpreter.getTypeIfRefinable(param, blindScope)).thenReturn(paramType);

        when(callee.getFirstChild()).thenReturn(left);
        when(callee.getLastChild()).thenReturn(right);
        when(left.getType()).thenReturn(Node.Type.NAME);
        when(left.getString()).thenReturn("goog");
        when(right.getType()).thenReturn(Node.Type.STRING);
        when(right.getString()).thenReturn("VALID_KEY");

        // Using reflection to inject the restricter into the private map if necessary, 
        // but for this unit test, we simulate the behavior by assuming the logic flows.
        // Since we can't easily inject into a private map without more context, 
        // we assume the environment allows us to trigger the path if we mock the internal map or use a subclass.

        // However, given the prompt, we will mock the 'restricters' field via reflection to ensure coverage.
        java.lang.reflect.Field field = ClosureReverseAbstractInterpreter.class.getDeclaredField("restricters");
        field.setAccessible(true);
        Map<String, Function<TypeRestriction, JSType>> mockRestricters = new HashMap<>();
        mockRestricters.put("VALID_KEY", restricter);
        field.set(interpreter, mockRestricters);

        when(interpreter.restrictParameter(eq(param), eq(paramType), eq(blindScope), eq(restricter), eq(true)))
            .thenReturn(expectedScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedScope, result);
        verify(interpreter).restrictParameter(param, paramType, blindScope, restricter, true);
    }
}
